/* Oniguruma engine #2: the very same onig.wasm that ships in vscode-oniguruma 1.7.0, translated ahead of time to C by `wasm2c` (wabt) and compiled natively.
 * No WebAssembly interpreter is needed at run time: the "wasm" is just C code operating on a linear-memory byte array. Needs wasm-rt-impl.c from wabt.
 * This file supplies what the JS Emscripten glue would: the three env imports + fd_write, string upload into linear memory, and call/trap handling. */
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include "onig.h"              /* generated by: wasm2c onig.wasm -o onig.c --module-name onig */
#include "wasm-rt-impl.h"
#include "wasm-rt-exceptions.h"
#include "onig_engine.h"

struct w2c_env { w2c_onig *inst; };
struct w2c_wasi__snapshot__preview1 { w2c_onig *inst; };
static w2c_onig g_inst; static struct w2c_env g_env; static struct w2c_wasi__snapshot__preview1 g_wasi; static int g_ready;

static uint8_t *M(void) { return w2c_onig_memory(&g_inst)->data; }

/* ---- imports the Emscripten glue normally provides ---- */
f64 w2c_env_emscripten_get_now(struct w2c_env *e) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec * 1e3 + t.tv_nsec / 1e6; }
void w2c_env_emscripten_memcpy_big(struct w2c_env *e, u32 dest, u32 src, u32 n) { memmove(M() + dest, M() + src, n); }
u32 w2c_env_emscripten_resize_heap(struct w2c_env *e, u32 requested) {
	wasm_rt_memory_t *m = w2c_onig_memory(&g_inst);
	if (requested <= m->size) { return 1; }
	uint64_t need = (requested - m->size + 65535) / 65536;
	return wasm_rt_grow_memory(m, need) != (uint64_t)-1;
}
u32 w2c_wasi__snapshot__preview1_fd_write(struct w2c_wasi__snapshot__preview1 *w, u32 fd, u32 iov, u32 iovcnt, u32 pnum) {
	uint8_t *mem = M(); u32 total = 0;
	for (u32 i = 0; i < iovcnt; i++) {
		u32 base, len; memcpy(&base, mem + iov + 8 * i, 4); memcpy(&len, mem + iov + 8 * i + 4, 4);
		fwrite(mem + base, 1, len, fd == 2 ? stderr : stdout); total += len;
	}
	memcpy(mem + pnum, &total, 4); return 0;
}

/* ---- engine ---- */
static u32 w_str_ptr, w_str_cap; static int w_str_id = -1;

static int w_init(void) {
	if (g_ready) { return 0; }
	wasm_rt_init(); g_env.inst = g_wasi.inst = &g_inst;
	wasm2c_onig_instantiate(&g_inst, &g_env, &g_wasi);
	if (wasm_rt_impl_try()) { return -1; }
	w2c_onig_0x5F_wasm_call_ctors(&g_inst);
	wasm_rt_set_unwind_target(NULL);
	g_ready = 1; return 0;
}

static void *w_create(const unsigned char **patterns, const int *lengths, int count, char *err, int errlen) {
	if (wasm_rt_impl_try()) { snprintf(err, errlen, "wasm trap while creating scanner"); return NULL; }
	u32 ptrs = w2c_onig_omalloc(&g_inst, 4 * (u32)(count ? count : 1)), lens = w2c_onig_omalloc(&g_inst, 4 * (u32)(count ? count : 1));
	u32 *pp = calloc((size_t)count + 1, 4);
	for (int i = 0; i < count; i++) { pp[i] = w2c_onig_omalloc(&g_inst, (u32)(lengths[i] ? lengths[i] : 1)); memcpy(M() + pp[i], patterns[i], (size_t)lengths[i]); }
	for (int i = 0; i < count; i++) { memcpy(M() + ptrs + 4 * i, &pp[i], 4); memcpy(M() + lens + 4 * i, &lengths[i], 4); }
	u32 sc = w2c_onig_createOnigScanner(&g_inst, ptrs, lens, (u32)count);
	for (int i = 0; i < count; i++) { w2c_onig_ofree(&g_inst, pp[i]); }
	free(pp); w2c_onig_ofree(&g_inst, lens); w2c_onig_ofree(&g_inst, ptrs);
	wasm_rt_set_unwind_target(NULL);
	if (!sc) { u32 e = w2c_onig_getLastOnigError(&g_inst); snprintf(err, errlen, "%s", (char *)(M() + e)); return NULL; }
	return (void *)(uintptr_t)sc;
}
static void w_free(void *h) { if (!wasm_rt_impl_try()) { w2c_onig_freeOnigScanner(&g_inst, (u32)(uintptr_t)h); } wasm_rt_set_unwind_target(NULL); }

static const int *w_find(void *h, int cacheId, const unsigned char *data, int len, int position, int option) {
	static int result[2 * (1 + 1000)];
	if (wasm_rt_impl_try()) { return NULL; }
	if (cacheId != w_str_id || !w_str_ptr) {                         /* upload the string once per OnigString id; the engine's match cache keys on that id */
		if ((u32)len > w_str_cap || !w_str_ptr) { if (w_str_ptr) { w2c_onig_ofree(&g_inst, w_str_ptr); } w_str_cap = (u32)(len < 256 ? 256 : len * 2); w_str_ptr = w2c_onig_omalloc(&g_inst, w_str_cap); }
		memcpy(M() + w_str_ptr, data, (size_t)len); w_str_id = cacheId;
	}
	u32 r = w2c_onig_findNextOnigScannerMatch(&g_inst, (u32)(uintptr_t)h, (u32)cacheId, w_str_ptr, (u32)len, (u32)position, (u32)option);
	wasm_rt_set_unwind_target(NULL);
	if (!r) { return NULL; }
	int n; memcpy(&n, M() + r + 4, 4); if (n > 1000) { return NULL; }
	memcpy(result, M() + r, (size_t)(2 + 2 * n) * 4);                /* copy out: the wasm static buffer is reused by the next call */
	return result;
}
const OnigEngine onig_engine_wasm2c = { "wasm2c (onig.wasm translated to C)", w_init, w_create, w_free, w_find };
